<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Reminder extends Model { protected $fillable=['user_id','pet_id','type','title','notes','due_at','completed_at','is_active']; protected $casts=['due_at'=>'datetime','completed_at'=>'datetime','is_active'=>'boolean']; public function user(){return $this->belongsTo(User::class);} public function pet(){return $this->belongsTo(Pet::class);} }